/*
 * Certification of jme_fixstar() on the JPL (CALCEPH) path: rigorous space
 * motion (eraStarpm from Hipparcos J1991.25 astrometry with parallax and
 * radial velocity) and the apparent place (deflection by Sun, Jupiter,
 * Saturn; annual aberration) against independent references generated by
 * tools/gen_star_fixtures.py (pyerfa eraStarpm + Skyfield + eraPnm06a).
 * Requires JME_TEST_JPL_KERNEL=<de440s.bsp> and CALCEPH; otherwise exit 77.
 */
#include "jme/jme.h"
#include "jme/jme_extended.h"
#include "fixtures/star_reference.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#define N(a)    ((int)(sizeof(a) / sizeof((a)[0])))
#define D2R     0.017453292519943295769236907692
#define TOL_MAS 0.02

static double max_mas[2];

/* angle between two directions, robust at all separations (atan2 form) */
static double sep_mas(double a1, double d1, double a2, double d2)
{
    const double u[3] =
        {cos(d1 * D2R) * cos(a1 * D2R), cos(d1 * D2R) * sin(a1 * D2R), sin(d1 * D2R)};
    const double v[3] =
        {cos(d2 * D2R) * cos(a2 * D2R), cos(d2 * D2R) * sin(a2 * D2R), sin(d2 * D2R)};
    const double c[3] =
        {u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]};
    return atan2(
               sqrt(c[0] * c[0] + c[1] * c[1] + c[2] * c[2]),
               u[0] * v[0] + u[1] * v[1] + u[2] * v[2]
           ) /
           D2R * 3.6e6;
}

static int check(int k, const char *what, const jme_star_fixture *f, int flags, const double *ref)
{
    double r[6];
    char error[256] = "";
    double s;
    if (jme_fixstar(f->star, f->jd_tt, flags, r, error) != JME_OK) {
        fprintf(stderr, "%s %s JD %.6f: %s\n", what, f->star, f->jd_tt, error);
        return 1;
    }
    s = sep_mas(r[0], r[1], ref[0], ref[1]);
    if (s > max_mas[k]) {
        max_mas[k] = s;
    }
    if (!(s <= TOL_MAS)) {
        fprintf(stderr, "%s %s JD %.6f: offset %.4f mas\n", what, f->star, f->jd_tt, s);
        return 1;
    }
    return 0;
}

int main(void)
{
    const char *kernel = getenv("JME_TEST_JPL_KERNEL");
    char error[256] = "";
    int i, failures = 0;

    if (kernel == 0 || kernel[0] == '\0' || !jme_jpl_is_available()) {
        printf("skipped: needs CALCEPH and JME_TEST_JPL_KERNEL\n");
        return 77;
    }
    if (jme_jpl_open(kernel, error) != JME_OK ||
        jme_set_astro_models_checked("IAU2006A;ENGINE=JPL", error) != JME_OK) {
        fprintf(stderr, "setup failed: %s\n", error);
        return 1;
    }
    for (i = 0; i < N(star_fixtures); i++) {
        const jme_star_fixture *f = &star_fixtures[i];
        failures += check(0, "icrs", f, JME_CALC_EQUATORIAL | JME_CALC_ICRS, f->gcrs);
        failures += check(1, "date", f, JME_CALC_EQUATORIAL, f->date);
    }
    jme_close();
    printf(
        "star_reference: %d places; max offsets icrs %.4f date %.4f mas\n",
        N(star_fixtures),
        max_mas[0],
        max_mas[1]
    );
    return failures == 0 ? 0 : 1;
}
